def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Compute my own donation rate
    if not my_history:
        my_generosity = 1.0   # assume generous initially
    else:
        donations = sum(1 for entry in my_history if entry['action'] == 'donate')
        my_generosity = donations / len(my_history)

    # Base threshold: lenient early (0.4), strict later (0.6)
    base_threshold = 0.4 if round_num < 10 else 0.6

    # Adjust threshold based on own generosity: if generous, be stricter (reward high reputation);
    # if stingy, be more forgiving (hope to build reciprocity)
    adjusted_threshold = base_threshold + 0.2 * (my_generosity - 0.5)
    adjusted_threshold = max(0.0, min(1.0, adjusted_threshold))

    return recipient_reputation > adjusted_threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Adaptive gamma: start small (0.1) and increase to 0.5 over rounds
    gamma = min(0.5, 0.1 + 0.02 * round_num)
    if observation['action'] == 'donate':
        # Reward donation strongly, but cap at 1.0
        score = 1.0
    else:
        # Punish non-donation moderately, but not too harshly
        score = -0.5
    # Update reputation with exponential moving average
    new_reputation = (1 - gamma) * current_reputation + gamma * score
    # Clamp to valid range
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Base threshold: stepwise decreasing over rounds (strict then more generous)
    if round_num <= 5:
        base = 0.6
    elif round_num <= 15:
        base = 0.4
    elif round_num <= 25:
        base = 0.3
    else:
        base = 0.2
    # Adjust threshold based on own recent donation rate
    recent = my_history[-10:] if len(my_history) >= 10 else my_history
    if recent:
        donations = sum(1 for a in recent if a == 'donate' or a is True)
        rate = donations / len(recent)
        # If we donated a lot recently, become stricter (higher threshold) to conserve resources
        # If we donated little, become more generous (lower threshold) to encourage cooperation
        adjustment = 0.3 * (rate - 0.5)
    else:
        adjustment = 0.0
    threshold = max(0.0, min(1.0, base + adjustment))
    return recipient_reputation >= threshold
